pub const WEB_HTML: &str = r##"<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1,user-scalable=no"><title>KidsTime</title>
<style>*{margin:0;padding:0;box-sizing:border-box}:root{--bg:#0f172a;--card:#1e293b;--accent:#3b82f6;--green:#22c55e;--yellow:#eab308;--red:#ef4444;--text:#e2e8f0;--gray:#64748b;--border:#334155}body{font-family:-apple-system,'Segoe UI',Roboto,sans-serif;background:var(--bg);color:var(--text);min-height:100vh;padding-bottom:80px}.header{background:var(--card);padding:16px 20px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;position:sticky;top:0;z-index:10}.header h1{font-size:20px;color:var(--green)}.header .status{font-size:12px;padding:4px 10px;border-radius:20px;background:var(--green);color:#000;font-weight:600}.header .status.off{background:var(--red);color:#fff}.card{background:var(--card);border-radius:16px;margin:16px;padding:20px;border:1px solid var(--border)}.card h2{font-size:14px;color:var(--gray);text-transform:uppercase;letter-spacing:1px;margin-bottom:12px}.timer{text-align:center;padding:30px 20px}.timer .big{font-size:64px;font-weight:700;font-variant-numeric:tabular-nums;line-height:1}.timer .big.green{color:var(--green)}.timer .big.yellow{color:var(--yellow)}.timer .big.red{color:var(--red)}.timer .label{font-size:14px;color:var(--gray);margin-top:8px}.progress-wrap{background:var(--border);border-radius:8px;height:10px;margin:16px 0 8px;overflow:hidden}.progress-bar{height:100%;border-radius:8px;transition:width 1s,background 1s}.progress-bar.green{background:var(--green)}.progress-bar.yellow{background:var(--yellow)}.progress-bar.red{background:var(--red)}.progress-label{font-size:12px;color:var(--gray);text-align:right}.stats{display:grid;grid-template-columns:1fr 1fr;gap:12px}.stat{background:var(--bg);border-radius:12px;padding:14px;text-align:center}.stat .val{font-size:22px;font-weight:700}.stat .lbl{font-size:11px;color:var(--gray);margin-top:4px}.now-active{display:flex;align-items:center;gap:12px;padding:14px;background:var(--bg);border-radius:12px}.now-active .icon{font-size:28px}.now-active .info{flex:1;min-width:0}.now-active .app-name{font-size:16px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.now-active .win-title{font-size:12px;color:var(--gray);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.app-list{max-height:240px;overflow-y:auto}.app-item{display:flex;align-items:center;padding:10px 0;border-bottom:1px solid var(--border)}.app-item:last-child{border-bottom:none}.app-item .name{flex:1;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.app-item .time{font-size:14px;font-weight:600;color:var(--accent);white-space:nowrap}.app-item .bar-bg{flex:0 0 80px;height:6px;background:var(--border);border-radius:3px;margin-left:12px;overflow:hidden}.app-item .bar-fill{height:100%;background:var(--accent);border-radius:3px}.timeline{max-height:200px;overflow-y:auto;font-size:13px}.timeline .entry{padding:6px 0;border-bottom:1px solid var(--border);display:flex;gap:10px}.timeline .entry .t{color:var(--gray);white-space:nowrap;font-size:12px;min-width:52px}.timeline .entry .w{flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.timeline .entry .p{color:var(--accent);font-size:12px;white-space:nowrap}.actions{display:flex;gap:10px;padding:0 16px;margin-top:8px}.actions button{flex:1;padding:14px;border:none;border-radius:12px;font-size:15px;font-weight:600;cursor:pointer;transition:opacity .2s}.actions button:active{opacity:.7}.btn-lock{background:var(--red);color:#fff}.btn-add{background:var(--accent);color:#fff}.login-wrap{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:80vh;padding:20px}.login-wrap h1{color:var(--green);font-size:28px;margin-bottom:8px}.login-wrap p{color:var(--gray);margin-bottom:24px;text-align:center}.login-wrap input{width:100%;max-width:300px;padding:14px 18px;border-radius:12px;border:1px solid var(--border);background:var(--card);color:var(--text);font-size:16px;margin-bottom:16px;outline:none}.login-wrap input:focus{border-color:var(--accent)}.login-wrap button{width:100%;max-width:300px;padding:14px;border:none;border-radius:12px;background:var(--green);color:#000;font-size:16px;font-weight:700;cursor:pointer}.login-hint{font-size:11px;color:var(--gray);text-align:center;margin-top:16px;max-width:300px}.toast{position:fixed;bottom:100px;left:50%;transform:translateX(-50%);background:var(--card);border:1px solid var(--border);color:var(--text);padding:12px 24px;border-radius:12px;font-size:14px;z-index:100;animation:fade 2s ease;pointer-events:none}@keyframes fade{0%{opacity:0;transform:translateX(-50%) translateY(10px)}15%{opacity:1;transform:translateX(-50%) translateY(0)}85%{opacity:1}100%{opacity:0;transform:translateX(-50%) translateY(-10px)}}</style></head><body><div id="app"></div><script>
const API='';
let token=localStorage.getItem('kt_token')||'';
let iid=null;
async function api(path,opts={}){
  try{const h={'Content-Type':'application/json'};if(token)h['Authorization']='Bearer '+token;const r=await fetch(API+path,{...opts,headers:{...h,...(opts.headers||{})}});if(r.status===401){token='';localStorage.removeItem('kt_token');showLogin();return null}if(!r.ok){const e=await r.json().catch(()=>({}));showToast(e.error||'Error');return null}return r.json()}catch(e){showToast('Connection error');return null}}
function showToast(m){const o=document.querySelector('.toast');if(o)o.remove();const d=document.createElement('div');d.className='toast';d.textContent=m;document.body.appendChild(d);setTimeout(()=>d.remove(),2100)}
function showLogin(){if(iid){clearInterval(iid);iid=null}document.getElementById('app').innerHTML='<div class="login-wrap"><h1>KidsTime</h1><p>Enter token from the desktop app to connect</p><input type="text" id="ti" placeholder="Token..." value="'+token+'"/><button onclick="doLogin()">Connect</button><p class="login-hint">The token is shown on the desktop app window.</p></div>';setTimeout(()=>{const e=document.getElementById('ti');if(e)e.focus()},100)}
async function doLogin(){const t=document.getElementById('ti').value.trim();if(!t)return;const r=await api('/api/status',{headers:{'Authorization':'Bearer '+t}});if(r){token=t;localStorage.setItem('kt_token',t);showDashboard()}}
function fmt(m){const h=Math.floor(m/60),mi=Math.floor(m%60);return String(h).padStart(2,'0')+':'+String(mi).padStart(2,'0')}
function pIcon(n){const s=n.toLowerCase();if(s.includes('chrome'))return'\u{1F310}';if(s.includes('firefox'))return'\u{1F525}';if(s.includes('discord'))return'\u{1F3AE}';if(s.includes('telegram'))return'\u2708';if(s.includes('steam'))return'\u{1F3AE}';if(s.includes('vlc')||s.includes('player'))return'\u{1F3AC}';if(s.includes('explorer'))return'\u{1F4C1}';return'\u{1F4CA}'}
function esc(s){if(!s)return'';const d=document.createElement('div');d.textContent=s;return d.innerHTML}
async function showDashboard(){if(iid)clearInterval(iid);document.getElementById('app').innerHTML='<div style="text-align:center;padding:40px">Loading...</div>';async function refresh(){const d=await api('/api/dashboard');if(d)render(d)}await refresh();iid=setInterval(refresh,5000)}
function render(d){
const st=d.is_blocked?'BLOCKED':(d.in_schedule?'ONLINE':'OUTSIDE SCHEDULE');
const sc=d.is_blocked?'off':(d.in_schedule?'':'off');
const rc=d.remaining_daily<=0?'red':d.remaining_daily<=15?'yellow':'green';
const pct=d.daily_limit>0?Math.min(100,(d.used_today/d.daily_limit)*100):100;
const bc=pct>=100?'red':pct>=80?'yellow':'green';
let al='';
if(d.apps&&d.apps.length>0){const mx=d.apps[0].minutes||1;al=d.apps.slice(0,10).map(a=>'<div class="app-item"><span class="name">'+esc(a.app)+'</span><span class="time">'+fmt(a.minutes)+'</span><div class="bar-bg"><div class="bar-fill" style="width:'+Math.round(a.minutes/mx*100)+'%"></div></div></div>').join('')}
let tl='';
if(d.recent_activity&&d.recent_activity.length>0){tl=d.recent_activity.slice(-20).reverse().map(e=>{const t=new Date(e.time);const ts=String(t.getHours()).padStart(2,'0')+':'+String(t.getMinutes()).padStart(2,'0');return'<div class="entry"><span class="t">'+ts+'</span><span class="w">'+esc(e.window||'')+'</span><span class="p">'+esc(e.process||'')+'</span></div>'}).join('')}
const sh=!d.in_schedule?'<div style="font-size:12px;padding:6px 12px;border-radius:8px;background:var(--yellow);color:#000;font-weight:600;text-align:center;margin:-8px 16px 8px">Outside schedule: '+d.schedule_start+' - '+d.schedule_end+'</div>':'';
document.getElementById('app').innerHTML='<div class="header"><h1>KidsTime</h1><span class="status '+sc+'">'+st+'</span></div>'+sh+'<div class="card timer"><div class="big '+rc+'">'+fmt(d.remaining_daily)+'</div><div class="label">remaining today</div><div class="progress-wrap"><div class="progress-bar '+bc+'" style="width:'+pct+'%"></div></div><div class="progress-label">'+Math.round(pct)+'% used</div></div><div class="card"><h2>Statistics</h2><div class="stats"><div class="stat"><div class="val">'+fmt(d.used_today)+'</div><div class="lbl">Used today</div></div><div class="stat"><div class="val">'+fmt(d.daily_limit)+'</div><div class="lbl">Daily limit</div></div><div class="stat"><div class="val">'+fmt(d.remaining_session)+'</div><div class="lbl">Session left</div></div><div class="stat"><div class="val">'+fmt(d.session_limit)+'</div><div class="lbl">Session limit</div></div></div></div><div class="card"><h2>Now Active</h2><div class="now-active"><span class="icon">'+pIcon(d.current_process)+'</span><div class="info"><div class="app-name">'+esc(d.current_process)+'</div><div class="win-title">'+esc(d.current_window)+'</div></div></div></div><div class="card"><h2>App Usage Today</h2><div class="app-list">'+(al||'<div style="color:var(--gray);text-align:center;padding:16px">No data yet</div>')+'</div></div><div class="card"><h2>Activity Log</h2><div class="timeline">'+(tl||'<div style="color:var(--gray);text-align:center;padding:16px">No data yet</div>')+'</div></div><div class="actions"><button class="btn-lock" onclick="doLock()">Lock Screen</button><button class="btn-add" onclick="doAddTime()">Add Time</button></div>'}
async function doLock(){if(!confirm('Lock the computer screen now?'))return;const r=await api('/api/lock',{method:'POST'});if(r)showToast('Screen locked!')}
async function doAddTime(){const m=prompt('How many minutes to add?','30');if(!m||isNaN(m)||m<1)return;const r=await api('/api/add-time',{method:'POST',body:JSON.stringify({minutes:parseInt(m)})});if(r)showToast('+'+m+' min added!')}
if(token)showDashboard();else showLogin();
</script></body></html>"##;